<?php

namespace App\Models\FinancialInstitutions;

// ══════════════════════════════════════════════════════════════════
//  LeaseAmortizationLine
//
//  Auto-generated amortization schedule for Treatment B + Capital leases.
//  One row per payment period. Generated by LeaseAmortizationService
//  (built July 2026 — see that file for the full calculation and
//  activation logic; this model was previously referencing a service
//  that didn't exist yet).
//  All monetary values calculated with bcmath — never PHP float.
//
//  Payments are NEVER posted automatically (confirmed with Mahmoud —
//  touching the bank account without the user's say-so could
//  misstate real cash if a payment is late). is_paid only flips to
//  true when the user deliberately records that payment.
//
//  @layer    Model
//  @depends  LeasingContract
// ══════════════════════════════════════════════════════════════════

use App\Models\Traits\BelongsToCompany;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use App\Models\Traits\SerializesDateOnly;

class LeaseAmortizationLine extends Model
{
    use BelongsToCompany, SerializesDateOnly;

    protected $table = 'lease_amortization_lines';

    protected $fillable = [
        'company_id', 'leasing_contract_id', 'period_number', 'payment_date',
        'payment_amount', 'principal_amount', 'interest_amount', 'balance_after',
        'is_paid', 'journal_entry_id',
    ];

    protected $casts = [
        'payment_amount'   => 'decimal:2',
        'principal_amount' => 'decimal:2',
        'interest_amount'  => 'decimal:2',
        'balance_after'    => 'decimal:2',
        'is_paid'          => 'boolean',
        'payment_date'     => 'date',
    ];

    public function contract(): BelongsTo
    {
        return $this->belongsTo(LeasingContract::class, 'leasing_contract_id');
    }

    public function scopeUnpaid(Builder $query): Builder { return $query->where('is_paid', false); }
    public function scopePaid(Builder $query): Builder   { return $query->where('is_paid', true); }
}
